struct curltime Curl_now(void) /* <=== Curl_now */ 
{
  /*
  ** time() returns the value of time in seconds since the Epoch.
  */
  struct curltime now;
  now.tv_sec = time(NULL);
  now.tv_usec = 0;
  return now;
}

void Curl_pgrsStartNow(struct Curl_easy *data) /* <=== Curl_pgrsStartNow */ 
{
  data->progress.speeder_c = 0; /* reset the progress meter display */
  data->progress.start = Curl_now();
  data->progress.is_t_startransfer_set = false;
  data->progress.ul_limit_start = data->progress.start;
  data->progress.dl_limit_start = data->progress.start;
  data->progress.ul_limit_size = 0;
  data->progress.dl_limit_size = 0;
  data->progress.downloaded = 0;
  data->progress.uploaded = 0;
  /* clear all bits except HIDE and HEADERS_OUT */
  data->progress.flags &= PGRS_HIDE|PGRS_HEADERS_OUT;
  Curl_ratelimit(data, data->progress.start);
}

char *Curl_get_line(char *buf, int len, FILE *input) /* <=== Curl_get_line */ 
{
  bool partial = FALSE;
  while(1) {
    char *b = fgets(buf, len, input);

    if(b) {
      size_t rlen = strlen(b);

      if(!rlen)
        break;

      if(b[rlen-1] == '\n') {
        /* b is \n terminated */
        if(partial) {
          partial = FALSE;
          continue;
        }
        return b;
      }
      else if(feof(input)) {
        if(partial)
          /* Line is already too large to return, ignore rest */
          break;

        if(rlen + 1 < (size_t) len) {
          /* b is EOF terminated, insert missing \n */
          b[rlen] = '\n';
          b[rlen + 1] = '\0';
          return b;
        }
        else
          /* Maximum buffersize reached + EOF
           * This line is impossible to add a \n to so we'll ignore it
           */
          break;
      }
      else
        /* Maximum buffersize reached */
        partial = TRUE;
    }
    else
      break;
  }
  return NULL;
}

static void hsts_free(struct stsentry *e) /* <=== hsts_free */ 
{
  free((char *)e->host);
  free(e);
}

void Curl_hsts_cleanup(struct hsts **hp) /* <=== Curl_hsts_cleanup */ 
{
  struct hsts *h = *hp;
  if(h) {
    struct Curl_llist_element *e;
    struct Curl_llist_element *n;
    for(e = h->list.head; e; e = n) {
      struct stsentry *sts = e->ptr;
      n = e->next;
      hsts_free(sts);
    }
    free(h->filename);
    free(h);
    *hp = NULL;
  }
}

CURLcode Curl_hsts_loadcb(struct Curl_easy *data, struct hsts *h) /* <=== Curl_hsts_loadcb */ 
{
  if(h)
    return hsts_pull(data, h);
  return CURLE_OK;
}

